/* Save status, export and import */
const saveToast=document.createElement('div');saveToast.id='save-toast';saveToast.setAttribute('role','status');saveToast.hidden=true;document.querySelector('body')?.append(saveToast);
function showSaveStatus(){saveToast.textContent=`Gespeichert · ${new Date().toLocaleTimeString('de-AT',{hour:'2-digit',minute:'2-digit'})}`;saveToast.hidden=false;clearTimeout(showSaveStatus.timer);showSaveStatus.timer=setTimeout(()=>saveToast.hidden=true,1800)}
const v16SaveCurrent=saveCurrent;saveCurrent=function(){const ok=v16SaveCurrent();if(ok)showSaveStatus();return ok};
function exportSave(id){const save=readSlots().find(slot=>slot.id===id);if(!save)return false;const blob=new Blob([JSON.stringify({game:'Doppel 6',version:17,exported:new Date().toISOString(),save},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`doppel-6-${save.club.toLowerCase().replace(/[^a-z0-9]+/g,'-')||'spielstand'}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return true}
function importSaveObject(raw){const candidate=raw?.save||raw;if(!candidate||candidate.schema!==3||!candidate.world||!Array.isArray(candidate.squad)||candidate.squad.length<5)return false;const slots=readSlots(),save=ensureChampionship(structuredClone(candidate));if(slots.some(item=>item.id===save.id))save.id=crypto.randomUUID();save.updated=new Date().toISOString();return persistSlots([...slots,save])}
startScreen.insertAdjacentHTML('beforeend','<section class="panel save-tools"><div class="section-heading"><h2>Spielstände sichern</h2><span>JSON-Datei</span></div><p class="help">Exportierte Spielstände können auf einem anderen Browser oder Gerät wieder importiert werden.</p><button id="import-save" class="menu-action wide">Spielstand importieren</button><input id="import-file" type="file" accept="application/json,.json" hidden><p id="import-status" class="help" role="status"></p></section>');
$('#import-save').onclick=()=>$('#import-file').click();$('#import-file').onchange=async event=>{
 const file=event.target.files?.[0];if(!file)return;
 const status=$('#import-status');let world=false;
 status.innerHTML='<span class="v67-loading" role="status"><span>Spielstand wird gelesen und geprüft …</span><span class="v67-loading-track" role="progressbar" aria-label="Spielstand importieren"><span></span></span></span>';
 try{
  if(file.size>50*1024*1024)throw Error('Die Datei ist für einen Spielstand zu groß.');
  const raw=JSON.parse(await file.text());
  world=typeof v61IsWorldExport==='function'&&v61IsWorldExport(raw);
  if(world){await v61ImportCareerData(raw);v61RenderSaves();status.textContent='Vereinswelt erfolgreich importiert.'}
  else{const ok=importSaveObject(raw);status.textContent=ok?'Spielstand erfolgreich importiert.':'Die Datei ist kein gültiger Doppel-6-Spielstand.';if(ok)drawSlots()}
 }catch(error){status.textContent=world?error.message:error.message==='Die Datei ist für einen Spielstand zu groß.'?error.message:'Die Datei konnte nicht gelesen werden.'}
 event.target.value='';
};
const v16DrawSlots=drawSlots;drawSlots=function(){v16DrawSlots();const saves=readSlots();$('#save-list').querySelectorAll('.save-slot').forEach((row,index)=>{const actions=row.querySelector('.privacy-actions'),save=saves[index];if(actions&&save&&!actions.querySelector('[data-export]')){actions.insertAdjacentHTML('beforeend',`<button class="menu-action" data-export="${escapeHTML(save.id)}">Exportieren</button>`);actions.querySelector('[data-export]').onclick=()=>exportSave(save.id)}})};

function decorateQol(){if(!activeSave||activeSave.finance?.gameOver)return;ensureQol(activeSave);const intro=clubCenter.querySelector('.intro');intro?.insertAdjacentHTML('afterend',timelineHTML());const squad=clubCenter.querySelector('.squad-list')?.closest('.panel'),financePanel=clubCenter.querySelector('.finance-panel');(squad||financePanel||intro)?.insertAdjacentHTML('beforebegin',warningsHTML());const saveButton=clubCenter.querySelector('#center-save');saveButton?.insertAdjacentHTML('beforebegin',newsHTML());clubCenter.querySelectorAll('[data-quick]').forEach(button=>button.onclick=()=>applyQuickLineup(button.dataset.quick));const read=clubCenter.querySelector('#news-read');if(read)read.onclick=()=>{for(const item of activeSave.news)item.read=true;saveCurrent();renderCenter()};
 const position=clubCenter.querySelector('#market-position'),sort=clubCenter.querySelector('#market-sort'),watch=clubCenter.querySelector('#market-watch');if(position)position.onchange=()=>setMarketFilter('position',position.value);if(sort)sort.onchange=()=>setMarketFilter('sort',sort.value);if(watch)watch.onchange=()=>setMarketFilter('watchOnly',watch.checked);
 clubCenter.querySelectorAll('[data-watch]').forEach(button=>button.onclick=()=>toggleWatch(button.dataset.watch));clubCenter.querySelectorAll('[data-compare]').forEach(button=>button.onclick=()=>toggleCompare(button.dataset.compare));clubCenter.querySelectorAll('[data-bid]').forEach(button=>button.onclick=()=>{button.disabled=true;submitBid(button.dataset.bid,+button.dataset.multiplier)});clubCenter.querySelectorAll('[data-counter-accept]').forEach(button=>button.onclick=()=>acceptCounter(button.dataset.counterAccept));clubCenter.querySelectorAll('[data-counter-decline]').forEach(button=>button.onclick=()=>declineCounter(button.dataset.counterDecline));clubCenter.querySelectorAll('[data-free-sign]').forEach(button=>button.onclick=()=>{button.disabled=true;signFreeAgent(button.dataset.freeSign)});clubCenter.querySelectorAll('[data-sale-accept]').forEach(button=>button.onclick=()=>acceptSaleOffer(button.dataset.saleAccept));clubCenter.querySelectorAll('[data-sale-decline]').forEach(button=>button.onclick=()=>declineSaleOffer(button.dataset.saleDecline));const nextDay=clubCenter.querySelector('#next-market-day'),deadline=clubCenter.querySelector('#deadline-button');if(nextDay)nextDay.onclick=()=>{nextDay.disabled=true;advanceTransferDay()};if(deadline)deadline.onclick=requestDeadline;document.querySelectorAll('footer span:first-child').forEach(element=>element.textContent='Doppel 6 / PROTOTYP 39')}

